#include <cstdint>
#include <atomic>

struct Limits { uint32_t max_size; int64_t max_notional; int64_t max_pos; int32_t collar_ticks; uint32_t max_msgs_per_sec; };
enum class Risk { OK, SIZE, NOTIONAL, PRICE, POSITION, RATE, DISABLED, ERROR };

class PreTradeRisk {
public:
    // Returns OK or the first failing reason. Tens of ns; on doubt -> reject.
    Risk check(bool buy, int32_t tick, uint32_t qty, int32_t mkt_mid) const noexcept {
        if (!enabled_.load(std::memory_order_relaxed)) return Risk::DISABLED;
        if (qty == 0 || qty > lim_.max_size)                  return Risk::SIZE;
        const int64_t notional = (int64_t)tick * qty;          // proxy; use real price
        if (notional > lim_.max_notional)                      return Risk::NOTIONAL;
        if (std::abs(tick - mkt_mid) > lim_.collar_ticks)      return Risk::PRICE;   // collar
        const int64_t newpos = position_ + (buy ? (int64_t)qty : -(int64_t)qty);
        if (std::abs(newpos) > lim_.max_pos)                   return Risk::POSITION;
        if (msgs_this_sec_ >= lim_.max_msgs_per_sec)           return Risk::RATE;
        return Risk::OK;
    }
    void on_send(uint32_t)  { ++msgs_this_sec_; }              // rate accounting
    void on_fill(bool buy, uint32_t qty) { position_ += buy ? (int64_t)qty : -(int64_t)qty; }
    void kill() { enabled_.store(false, std::memory_order_relaxed); }   // part of kill switch
private:
    Limits lim_{};
    int64_t position_ = 0;
    uint32_t msgs_this_sec_ = 0;
    std::atomic<bool> enabled_{true};
};

struct KillSwitch {
    PreTradeRisk& risk; OMS& oms; bool flatten;

    void trigger(const char* reason) {
        risk.kill();                 // 1) block all new orders immediately (fail-closed)
        oms.cancel_all();            // 2) mass-cancel resting orders
        if (flatten) oms.flatten();  // 3) market-out to flat (or freeze per policy)
        alert(reason);               // page humans; log; require manual re-enable
    }
};

// Auto-tripwires evaluated off the hot path on a monitor thread:
void monitor(KillSwitch& ks, const Metrics& m, const Limits& lim) {
    if (m.pnl_drawdown > lim_pnl)       ks.trigger("PnL drawdown");
    if (m.gross_exposure > lim_exp)     ks.trigger("exposure breach");
    if (m.reject_rate > lim_rej)        ks.trigger("reject spike");
    if (m.md_stale_ms > lim_stale)      ks.trigger("market data stale");
    if (m.heartbeat_missed)             ks.trigger("heartbeat lost");
}
